source "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"

_choice_dbname() {
    _argc_util_cache 300 _choice_dbname_uncached "pg_restore_dbname:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_dbname_uncached() {
    _helper_psql_query 'select datname from pg_database where datallowconn order by 1'
}

_choice_function() {
    _argc_util_cache 300 _choice_function_uncached "pg_restore_function:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_function_uncached() {
    _helper_psql_query "select p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg\_%' order by 1 limit 500" "${argc_dbname:-postgres}"
}

_choice_index() {
    _argc_util_cache 300 _choice_index_uncached "pg_restore_index:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_index_uncached() {
    _helper_psql_query "select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relkind = 'i' and n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg\_%' order by 1 limit 500" "${argc_dbname:-postgres}"
}

_choice_role() {
    _argc_util_cache 300 _choice_role_uncached "pg_restore_role:${argc_dbname:-}:${argc_host:-}:${argc_port:-}"
}

_choice_role_uncached() {
    _helper_psql_query 'select rolname from pg_roles order by 1' "${argc_dbname:-postgres}" 0
}

_choice_schema() {
    _argc_util_cache 300 _choice_schema_uncached "pg_restore_schema:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_schema_uncached() {
    _helper_psql_query "select nspname from pg_namespace where nspname not in ('pg_catalog','information_schema') and nspname not like 'pg\_%' order by 1" "${argc_dbname:-postgres}"
}

_choice_table() {
    _argc_util_cache 300 _choice_table_uncached "pg_restore_table:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_table_uncached() {
    _helper_psql_query "select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relkind in ('r','p','v','m','f') and n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg\_%' order by 1 limit 500" "${argc_dbname:-postgres}"
}

_choice_trigger() {
    _argc_util_cache 300 _choice_trigger_uncached "pg_restore_trigger:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_trigger_uncached() {
    _helper_psql_query "select t.tgname from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where not t.tgisinternal and n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg\_%' order by 1 limit 500" "${argc_dbname:-postgres}"
}

_choice_username() {
    _argc_util_cache 300 _choice_username_uncached "pg_restore_username:${argc_dbname:-}:${argc_host:-}:${argc_port:-}"
}

